-- Splynn Dimensional Market: the 2 magic weapon tattoos and 10 power tattoos of printed 102-104.
-- 12 spells rows.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~356-splynn-tattoos-a.sql
--
-- Written by scripts/rows-sql.mjs from 1 worker file(s). Every value is
-- printable ASCII and every row cites its book. Rows are keyed on their
-- portable identity, never an id; a row already held is left as it is.

INSERT OR IGNORE INTO spells (name, level, ppe, ppe_note, variant_note, source, source_book, system, range, duration, damage, saving_throw, area_of_effect, casting_time, description, same_spell_as, tradition, ppe_permanent) VALUES
  ('Tattoo: Weapon Smashing or Impaling a Heart (anti-P.P.E.)', 0, 20, '30 when combined with the wing feature (printed 102). Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.102', 'rifts', NULL, '15 minutes per level of experience or until cancelled', 'The weapon''s normal S.D.C. damage, taken from the victim''s P.P.E. instead of its body; the same figure as M.D. against a barrier made purely of magic energy', '14 or higher vs magic; a successful save means no P.P.E. is lost', NULL, 'One melee action', 'Image: a weapon smashing into or run through a heart. Creates a magic weapon that does no physical harm: whatever S.D.C. damage the weapon would normally deal is drained from the target''s P.P.E. instead (a knife that would do 1D6 S.D.C. drains 1D6 P.P.E.). Works only on living beings, and the blow may be parried or dodged like any other. Against a force field or barrier built wholly of P.P.E. (Armor of Ithan, Energy Field and the like) its S.D.C. figure counts as M.D.; enchanted Bio-Wizard or Techno-Wizard armor, magically hardened metal, Millennium Tree armor and the like are not affected. It does not stack with the dripping-blood or flaming weapon tattoos, though wings can be added.', NULL, 'tattoo', NULL),
  ('Tattoo: Weapon Smashing or Impaling a Skull (anti-I.S.P.)', 0, 10, '20 when combined with the wing feature (printed 102). Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.102-103', 'rifts', NULL, '15 minutes per level of experience or until cancelled', 'The weapon''s normal S.D.C. damage, taken from the victim''s I.S.P. instead of its body; the same figure as M.D. against a defense made purely of psionic energy', '14 or higher vs magic against a blow that lands', NULL, 'One melee action', 'Image: a weapon smashing into or run through a skull. Creates a magic weapon that causes no physical injury: the S.D.C. damage it would ordinarily deal is drained from the target''s I.S.P. (a sword normally doing 2D4 S.D.C. drains 2D4 I.S.P.). Affects living beings only, and can be parried or dodged as usual. Against a barrier made entirely of psionic energy, such as a Telekinetic Force Field or Psi-Shield, its S.D.C. figure counts as M.D.; matter merely toughened by psionics, like the stone weapons of the Pucara giants, is not affected. It does not stack with the dripping-blood or flaming weapon tattoos, though wings can be added.', NULL, 'tattoo', NULL),
  ('Tattoo: Beautiful Dancer (hypnotic gaze)', 0, 15, 'Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.103', 'rifts', '12 feet (3.65 m) and eye contact', 'Each suggestion lasts as long as its command requires; the T-Man keeps the ability for two minutes per level of experience', NULL, NULL, NULL, 'One melee action', 'Image: a beautiful dancer. While it is active the T-Man can use Hypnotic Suggestion, working exactly as the super-psionic power of that name, through his gaze. He may attempt it as many times per melee as he has hand to hand attacks.', NULL, 'tattoo', NULL),
  ('Tattoo: Black Sun (darkness powers)', 0, 40, 'Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.103', 'rifts', 'Self, or a 5 foot (1.5 m) radius per level of experience', 'Five minutes per level of experience', NULL, NULL, NULL, 'One melee action', 'Image: a black sun ringed by wavy rays. Grants a limited command of darkness, usable as many times per melee as the T-Man has hand to hand attacks: nightvision to 600 feet (182.9 m) that also pierces magical darkness and picks out Shadow Beasts and similar shadow creatures even while they are melded into shadow; Shadow Meld, as the spell; and Cloak of Darkness, as the spell from Rifts Federation of Magic.', NULL, 'tattoo', NULL),
  ('Tattoo: Bleeding Heart (power punch)', 0, 20, 'Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.103', 'rifts', NULL, 'Two minutes per level of experience or until cancelled', 'Punches and other bare-handed blows do Mega-Damage, as if the T-Man''s P.S. were supernatural', NULL, NULL, 'One melee action', 'Image: a bleeding heart. The T-Man''s empty hands strike for Mega-Damage as though his strength were supernatural, though his P.S. number and what he can lift or carry do not change; damage is the only thing it alters. He can also parry M.D. melee blows barehanded, but parrying energy blasts or projectiles is at -10 and gets no parry bonuses.', NULL, 'tattoo', NULL),
  ('Tattoo: Cracked or Broken Skull (mental attack)', 0, 25, 'Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.103', 'rifts', 'Touch', 'A victim suffers for one melee round; the T-Man keeps the ability for one minute per level of experience', NULL, '14 or higher vs magic; a successful save means no effect', NULL, 'One melee action', 'Image: a cracked or shattered skull. A touch inflicts a splitting headache much like the Agony spell, but aimed at the head. A victim who fails to save loses half his attacks per melee and half his speed, is -2 on all combat bonuses and -25% on most skills, and cannot perform skills that demand real concentration, such as Sniper or Cardsharp. The T-Man may try it as many times per melee as he has hand to hand attacks.', NULL, 'tattoo', NULL),
  ('Tattoo: Flaming Eye (fire projection and thermo-imaging)', 0, 20, 'Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.103', 'rifts', 'Flame attack 100 feet (30.5 m) plus 50 feet (15.2 m) per level of experience; thermal sight 600 feet (183 m)', 'Five minutes per level of experience', '1D4 M.D. per level of experience', NULL, NULL, 'One melee action', 'Image: an eyeball wreathed in flame. The T-Man sees heat as an infrared thermo-imager does, out to 600 feet (183 m), and can shoot fire from his eyes as many times per melee as he has hand to hand attacks, at +2 to strike with no other bonuses. The page gives the flame two ranges: the Range line (recorded here) adds 50 ft per level to a 100 ft base, while the Powers paragraph says 60 feet (18.3 m).', NULL, 'tattoo', NULL),
  ('Tattoo: Heart in Two Pieces (strength drain)', 0, 30, 'Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.103-104', 'rifts', 'Touch', 'A victim suffers for one melee round per level of the T-Man''s experience; the T-Man keeps the ability for one minute per level of experience', NULL, '14 or higher vs magic', NULL, 'One melee action', 'Image: a heart split in two. The touch or blow seems ordinary until the victim tries to hit back and finds his P.S. halved, with all his damage figures reduced to match. Lesser supernatural beings and creatures of magic are affected too; adult dragons, the undead, gods, demigods, godlings and demon lords are immune. The T-Man may try it as many times per melee as he has hand to hand attacks.', NULL, 'tattoo', NULL),
  ('Tattoo: Heart of Steel (courage)', 0, 25, 'Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.104', 'rifts', 'Self', 'Five minutes per level of experience', NULL, NULL, NULL, 'One melee action', 'Image: a heart of steel. Steadies the T-Man against fear: +4 to save vs Horror Factor and every fear-causing attack, +2 to save against mind control and illusion, and +5 to save vs possession.', NULL, 'tattoo', NULL),
  ('Tattoo: Heart Wrapped in Thorns (poison touch)', 0, 35, 'Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.104', 'rifts', 'Touch', 'A victim suffers for one minute per level of the T-Man''s experience; the T-Man keeps the ability for two minutes per level of experience', NULL, '14 or higher vs magic; a successful save means no effect', NULL, 'One melee action', 'Image: a heart bound in thorns. A touch convinces the victim he has been poisoned. The penalties are psychosomatic: half his attacks per melee and half his speed, -4 on all combat bonuses, -4 on saves against actual poisons, -30% on all skills, and dizziness and nausea. The T-Man may try it as many times per melee as he has hand to hand attacks.', NULL, 'tattoo', NULL),
  ('Tattoo: Skeleton in Chains (constrain the undead)', 0, 20, 'Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.104', 'rifts', 'Touch or up to 200 feet (61 m)', 'One minute per level of experience', NULL, 'None for mindless undead such as zombies and mummies; 14 or higher for others such as vampires; master vampires and superior undead are immune', NULL, 'One melee action', 'Image: a chained skeleton. A wave of the hand holds one undead creature motionless for 1D4 melee rounds; only one can be held at a time. The T-Man may try it as many times per melee as he has hand to hand attacks.', NULL, 'tattoo', NULL),
  ('Tattoo: Wolf''s Head with Glowing Eyes (hunting prowess)', 0, 30, 'Double for anyone who is not a full Tattooed Man (Atlantis, printed 85).', NULL, 'import', 'Rifts World Book 21: Splynn Dimensional Market p.104', 'rifts', 'Self', 'Five minutes per level of experience', NULL, NULL, NULL, 'One melee action', 'Image: a wolf''s head with shining eyes. A variant of the Eyes of the Wolf spell: +1 to initiative, nightvision to 100 feet (30.5 m), tracking or recognizing animals by sight at 50%, telling edible plants, fruit and meat at 75%, and sensing traps at 35%.', NULL, 'tattoo', NULL);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 12 spells rows are in' AS assertion, count(*) AS got, 12 AS want
  FROM spells WHERE name IN ('Tattoo: Weapon Smashing or Impaling a Heart (anti-P.P.E.)', 'Tattoo: Weapon Smashing or Impaling a Skull (anti-I.S.P.)', 'Tattoo: Beautiful Dancer (hypnotic gaze)', 'Tattoo: Black Sun (darkness powers)', 'Tattoo: Bleeding Heart (power punch)', 'Tattoo: Cracked or Broken Skull (mental attack)', 'Tattoo: Flaming Eye (fire projection and thermo-imaging)', 'Tattoo: Heart in Two Pieces (strength drain)', 'Tattoo: Heart of Steel (courage)', 'Tattoo: Heart Wrapped in Thorns (poison touch)', 'Tattoo: Skeleton in Chains (constrain the undead)', 'Tattoo: Wolf''s Head with Glowing Eyes (hunting prowess)') AND source_book IS NOT NULL;

